   ===================================================================== */
SET QUOTED_IDENTIFIER ON;
SET ANSI_NULLS ON;
GO
ALTER TABLE dbo.ChiTietHoaDon DISABLE TRIGGER trg_ChiTietHoaDon_KhoaHoaDonDaThanhToan;
